221	function listAvailableSkills(): AvailableSkill[] {
222	  const homeDir = process.env.HOME || process.env.USERPROFILE || "";
223	  const claudeSkillsDir = path.join(homeDir, ".claude", "skills");
224	  const paperclipSkillsDir = resolvePaperclipSkillsDir();
225	
226	  // Build set of Paperclip-managed skill names
227	  const paperclipSkillNames = new Set<string>();
228	  if (paperclipSkillsDir) {
229	    try {
230	      for (const entry of fs.readdirSync(paperclipSkillsDir, { withFileTypes: true })) {
231	        if (entry.isDirectory()) paperclipSkillNames.add(entry.name);
232	      }
233	    } catch { /* skip */ }
234	  }
235	
236	  const skills: AvailableSkill[] = [];
237	
238	  try {
239	    const entries = fs.readdirSync(claudeSkillsDir, { withFileTypes: true });
240	    for (const entry of entries) {
241	      if (!entry.isDirectory() && !entry.isSymbolicLink()) continue;
242	      if (entry.name.startsWith(".")) continue;
243	      const skillMdPath = path.join(claudeSkillsDir, entry.name, "SKILL.md");
244	      let description = "";
245	      try {
246	        const md = fs.readFileSync(skillMdPath, "utf8");
247	        description = parseSkillFrontmatter(md).description;
248	      } catch { /* no SKILL.md or unreadable */ }
249	      skills.push({
250	        name: entry.name,
251	        description,
252	        isPaperclipManaged: paperclipSkillNames.has(entry.name),
253	      });
254	    }
255	  } catch { /* ~/.claude/skills/ doesn't exist */ }
256	
257	  skills.sort((a, b) => a.name.localeCompare(b.name));
258	  return skills;
259	}
