282	function normalizeHostname(value: string | null | undefined): string | null {
283	  if (!value) return null;
284	  const trimmed = value.trim();
285	  if (!trimmed) return null;
286	  if (trimmed.startsWith("[")) {
287	    const end = trimmed.indexOf("]");
288	    return end > 1
289	      ? trimmed.slice(1, end).toLowerCase()
290	      : trimmed.toLowerCase();
291	  }
292	  const firstColon = trimmed.indexOf(":");
293	  if (firstColon > -1) return trimmed.slice(0, firstColon).toLowerCase();
294	  return trimmed.toLowerCase();
295	}
