297	function normalizeHeaderValue(
298	  value: unknown,
299	  depth: number = 0
300	): string | null {
301	  const direct = nonEmptyTrimmedString(value);
302	  if (direct) return direct;
303	  if (!isPlainObject(value) || depth >= 3) return null;
304	
305	  const candidateKeys = [
306	    "value",
307	    "token",
308	    "secret",
309	    "apiKey",
310	    "api_key",
311	    "auth",
312	    "authToken",
313	    "auth_token",
314	    "accessToken",
315	    "access_token",
316	    "authorization",
317	    "bearer",
318	    "header",
319	    "raw",
320	    "text",
321	    "string"
322	  ];
323	  for (const key of candidateKeys) {
324	    if (!Object.prototype.hasOwnProperty.call(value, key)) continue;
325	    const normalized = normalizeHeaderValue(
326	      (value as Record<string, unknown>)[key],
327	      depth + 1
328	    );
329	    if (normalized) return normalized;
330	  }
331	
332	  const entries = Object.entries(value as Record<string, unknown>);
333	  if (entries.length === 1) {
334	    const [singleKey, singleValue] = entries[0];
335	    const normalizedKey = singleKey.trim().toLowerCase();
336	    if (
337	      normalizedKey !== "type" &&
338	      normalizedKey !== "version" &&
339	      normalizedKey !== "secretid" &&
340	      normalizedKey !== "secret_id"
341	    ) {
342	      const normalized = normalizeHeaderValue(singleValue, depth + 1);
343	      if (normalized) return normalized;
344	    }
345	  }
346	
347	  return null;
348	}
