350	function extractHeaderEntries(input: unknown): Array<[string, unknown]> {
351	  if (isPlainObject(input)) {
352	    return Object.entries(input);
353	  }
354	  if (!Array.isArray(input)) {
355	    return [];
356	  }
357	
358	  const entries: Array<[string, unknown]> = [];
359	  for (const item of input) {
360	    if (Array.isArray(item)) {
361	      const key = nonEmptyTrimmedString(item[0]);
362	      if (!key) continue;
363	      entries.push([key, item[1]]);
364	      continue;
365	    }
366	    if (!isPlainObject(item)) continue;
367	
368	    const mapped = item as Record<string, unknown>;
369	    const explicitKey =
370	      nonEmptyTrimmedString(mapped.key) ??
371	      nonEmptyTrimmedString(mapped.name) ??
372	      nonEmptyTrimmedString(mapped.header);
373	    if (explicitKey) {
374	      const explicitValue = Object.prototype.hasOwnProperty.call(
375	        mapped,
376	        "value"
377	      )
378	        ? mapped.value
379	        : Object.prototype.hasOwnProperty.call(mapped, "token")
380	        ? mapped.token
381	        : Object.prototype.hasOwnProperty.call(mapped, "secret")
382	        ? mapped.secret
383	        : mapped;
384	      entries.push([explicitKey, explicitValue]);
385	      continue;
386	    }
387	
388	    const singleEntry = Object.entries(mapped);
389	    if (singleEntry.length === 1) {
390	      entries.push(singleEntry[0] as [string, unknown]);
391	    }
392	  }
393	
394	  return entries;
395	}
